1	/**
2	 * NexiFy — Responsive Utilities
3	 * js/responsive-utils.js
4	 *
5	 * Handles: breakpoint detection, device analytics, safe area,
6	 * lazy loading enhancement, sticky CTA bar, scroll header state.
7	 */
8	
9	(function () {
10	  'use strict';
11	
12	  /* ──────────────────────────────────────────────
13	     1. Breakpoint System
14	  ────────────────────────────────────────────── */
15	  const BP = {
16	    xs:  480,
17	    sm:  767,
18	    md:  834,
19	    lg:  1024,
20	    xl:  1440,
21	    xxl: 2560
22	  };
23	
24	  /**
25	   * Get current breakpoint name
26	   * @returns {string}
27	   */
28	  function getBreakpoint() {
29	    const w = window.innerWidth;
30	    if (w <= BP.xs)  return 'mobile-small';
31	    if (w <= BP.sm)  return 'mobile-large';
32	    if (w <= BP.md)  return 'tablet-portrait';
33	    if (w <= BP.lg)  return 'tablet-landscape';
34	    if (w <= BP.xl)  return 'laptop';
35	    if (w <= BP.xxl) return 'desktop';
36	    return 'ultrawide';
37	  }
38	
39	  /**
40	   * Check if current viewport is mobile
41	   * Uses pointer coarse + narrow viewport
42	   */
43	  function isMobile() {
44	    return window.innerWidth <= 767 ||
45	           window.matchMedia('(pointer: coarse)').matches;
46	  }
47	
48	  /**
49	   * Check if current viewport is touch device
50	   */
51	  function isTouchDevice() {
52	    return ('ontouchstart' in window) ||
53	           (navigator.maxTouchPoints > 0) ||
54	           window.matchMedia('(pointer: coarse)').matches;
55	  }
56	
57	  // Expose to window for other scripts
58	  window.NexifyResponsive = { getBreakpoint, isMobile, isTouchDevice };
59	
60	  /* ──────────────────────────────────────────────
61	     2. Set device class on <html> for CSS hooks
62	  ────────────────────────────────────────────── */
63	  function setDeviceClasses() {
64	    const html = document.documentElement;
65	    const bp = getBreakpoint();
66	
67	    // Remove old bp classes
68	    html.classList.remove(
69	      'bp-mobile-small', 'bp-mobile-large', 'bp-tablet-portrait',
70	      'bp-tablet-landscape', 'bp-laptop', 'bp-desktop', 'bp-ultrawide'
71	    );
72	    html.classList.add('bp-' + bp);
73	
74	    // Touch/hover classification
75	    if (isTouchDevice()) {
76	      html.classList.add('touch-device');
77	      html.classList.remove('pointer-device');
78	    } else {
79	      html.classList.add('pointer-device');
80	      html.classList.remove('touch-device');
81	    }
82	  }
83	
84	  setDeviceClasses();
85	  window.addEventListener('resize', debounce(setDeviceClasses, 150));
86	
87	  /* ──────────────────────────────────────────────
88	     3. Analytics: Device Tracking
89	  ────────────────────────────────────────────── */
90	  function trackDeviceInfo() {
91	    const info = {
92	      breakpoint: getBreakpoint(),
93	      viewportWidth: window.innerWidth,
94	      viewportHeight: window.innerHeight,
95	      devicePixelRatio: window.devicePixelRatio || 1,
96	      isTouch: isTouchDevice(),
97	      orientation: window.innerWidth > window.innerHeight ? 'landscape' : 'portrait',
98	      platform: navigator.platform || 'unknown',
99	      userAgent: navigator.userAgent
100	    };
101	
102	    // Google Analytics 4 — custom dimensions
103	    if (typeof gtag === 'function') {
104	      gtag('set', {
105	        device_type: info.breakpoint,
106	        screen_dpr: info.devicePixelRatio.toFixed(1)
107	      });
108	    }
109	
110	    // Store for debugging
111	    window.__nexifyDevice = info;
112	
113	    return info;
114	  }
115	
116	  // Run on load
117	  if (document.readyState === 'loading') {
118	    document.addEventListener('DOMContentLoaded', trackDeviceInfo);
119	  } else {
120	    trackDeviceInfo();
121	  }
122	
123	  /* ──────────────────────────────────────────────
124	     4. Sticky Header — Scroll State
125	  ────────────────────────────────────────────── */
126	  (function initStickyHeader() {
127	    const header = document.querySelector('.site-header');
128	    if (!header) return;
129	
130	    let lastScroll = 0;
131	    let ticking = false;
132	
133	    function updateHeader() {
134	      const currentScroll = window.scrollY;
135	
136	      if (currentScroll > 40) {
137	        header.classList.add('scrolled');
138	      } else {
139	        header.classList.remove('scrolled');
140	      }
141	
142	      // Hide on scroll down, show on scroll up (mobile)
143	      if (window.innerWidth <= 767) {
144	        if (currentScroll > lastScroll && currentScroll > 200) {
145	          header.classList.add('header-hidden');
146	        } else {
147	          header.classList.remove('header-hidden');
148	        }
149	      }
150	
151	      lastScroll = currentScroll;
152	      ticking = false;
153	    }
154	
155	    window.addEventListener('scroll', function () {
156	      if (!ticking) {
157	        requestAnimationFrame(updateHeader);
158	        ticking = true;
159	      }
160	    }, { passive: true });
161	  })();
162	
163	  /* ──────────────────────────────────────────────
164	     5. Sticky CTA Bar — Mobile
165	  ────────────────────────────────────────────── */
166	  (function initStickyCTA() {
167	    const ctaBar = document.querySelector('.sticky-cta-bar');
168	    if (!ctaBar) return;
169	
170	    // Add body class for padding compensation
171	    document.body.classList.add('has-sticky-cta');
172	
173	    // Hide when user scrolls near footer
174	    const footer = document.querySelector('.site-footer');
175	    if (!footer) return;
176	
177	    const observer = new IntersectionObserver(function (entries) {
178	      entries.forEach(function (entry) {
179	        if (entry.isIntersecting) {
180	          ctaBar.style.opacity = '0';
181	          ctaBar.style.pointerEvents = 'none';
182	        } else {
183	          ctaBar.style.opacity = '1';
184	          ctaBar.style.pointerEvents = 'auto';
185	        }
186	      });
187	    }, { threshold: 0.1 });
188	
189	    observer.observe(footer);
190	  })();
191	
192	  /* ──────────────────────────────────────────────
193	     6. Lazy Image Loading Enhancement
194	  ────────────────────────────────────────────── */
195	  (function initLazyImages() {
196	    if ('IntersectionObserver' in window) {
197	      const imageObserver = new IntersectionObserver(function (entries) {
198	        entries.forEach(function (entry) {
199	          if (entry.isIntersecting) {
200	            const img = entry.target;
201	            img.classList.add('loaded');
202	            imageObserver.unobserve(img);
203	          }
204	        });
205	      }, {
206	        rootMargin: '200px 0px'
207	      });
208	
209	      document.querySelectorAll('img[loading="lazy"]').forEach(function (img) {
210	        imageObserver.observe(img);
211	      });
212	    } else {
213	      // Fallback: show all images
214	      document.querySelectorAll('img[loading="lazy"]').forEach(function (img) {
215	        img.classList.add('loaded');
216	      });
217	    }
218	  })();
219	
220	  /* ──────────────────────────────────────────────
221	     7. Navigation Overlay (mobile)
222	  ────────────────────────────────────────────── */
223	  (function initNavOverlay() {
224	    // Create overlay element if not present
225	    if (!document.querySelector('.nav-overlay')) {
226	      const overlay = document.createElement('div');
227	      overlay.className = 'nav-overlay';
228	      overlay.setAttribute('aria-hidden', 'true');
229	      document.body.appendChild(overlay);
230	
231	      // Close nav when overlay is clicked
232	      overlay.addEventListener('click', function () {
233	        const nav = document.querySelector('.main-nav');
234	        const toggle = document.querySelector('.menu-toggle');
235	        if (nav && nav.classList.contains('is-open')) {
236	          nav.classList.remove('is-open');
237	          overlay.classList.remove('is-visible');
238	          document.body.style.overflow = '';
239	          if (toggle) toggle.setAttribute('aria-expanded', 'false');
240	        }
241	      });
242	    }
243	
244	    // Enhance existing menu toggle
245	    const toggle = document.querySelector('[data-testid="menu-toggle"]');
246	    const nav = document.querySelector('[data-testid="main-nav"]');
247	    const overlay = document.querySelector('.nav-overlay');
248	
249	    if (toggle && nav) {
250	      // Set initial ARIA
251	      toggle.setAttribute('aria-expanded', 'false');
252	      toggle.setAttribute('aria-controls', 'main-nav');
253	
254	      // Override existing click handler with enhanced version
255	      toggle.addEventListener('click', function (e) {
256	        const isOpen = nav.classList.toggle('is-open');
257	        toggle.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
258	
259	        if (overlay) {
260	          overlay.classList.toggle('is-visible', isOpen);
261	        }
262	
263	        // Prevent body scroll when nav is open (mobile)
264	        document.body.style.overflow = isOpen ? 'hidden' : '';
265	      });
266	
267	      // Close nav on escape key
268	      document.addEventListener('keydown', function (e) {
269	        if (e.key === 'Escape' && nav.classList.contains('is-open')) {
270	          nav.classList.remove('is-open');
271	          if (overlay) overlay.classList.remove('is-visible');
272	          document.body.style.overflow = '';
273	          toggle.setAttribute('aria-expanded', 'false');
274	          toggle.focus();
275	        }
276	      });
277	    }
278	  })();
279	
280	  /* ──────────────────────────────────────────────
281	     8. Orientation Change Handler
282	  ────────────────────────────────────────────── */
283	  window.addEventListener('orientationchange', function () {
284	    // Small delay for browser to update dimensions
285	    setTimeout(function () {
286	      setDeviceClasses();
287	
288	      // Close mobile nav on orientation change
289	      const nav = document.querySelector('.main-nav');
290	      const overlay = document.querySelector('.nav-overlay');
