.menu-toggle { display: none; min-width: 44px; min-height: 44px; width: 44px; height: 44px; border-radius: 10px; background: var(--c-blue-50); border: none; cursor: pointer; align-items: center; justify-content: center; transition: background .2s; }
.menu-toggle:hover, .menu-toggle:focus-visible { background: var(--c-blue-100, #d8e6f8); outline: 2px solid var(--c-blue); outline-offset: 2px; }
/* Hamburger → X animation */
.menu-toggle span { display: block; width: 20px; height: 2px; background: var(--c-blue); position: relative; transition: background .2s, transform .25s; }
.menu-toggle.is-open span { background: transparent; }
.menu-toggle span::before, .menu-toggle span::after { content: ''; position: absolute; left: 0; right: 0; height: 2px; background: var(--c-blue); transition: transform .25s, top .25s; }
.menu-toggle span::before { top: -6px; }
.menu-toggle span::after { top: 6px; }
.menu-toggle.is-open span::before { top: 0; transform: rotate(45deg); }
.menu-toggle.is-open span::after { top: 0; transform: rotate(-45deg); }

