      }
    });
  }

  // Enhance existing menu toggle
  const toggle = document.querySelector('[data-testid="menu-toggle"]');
  const nav = document.querySelector('[data-testid="main-nav"]');
  const overlay = document.querySelector('.nav-overlay');

