from playwright.sync_api import sync_playwright

with sync_playwright() as p:
    browser = p.chromium.launch(headless=True)
    context = browser.new_context(ignore_https_errors=True)
    page = context.new_page()

    # Intercept addEventListener to track if any listener gets added
    page.add_init_script("""
    (() => {
      const orig = EventTarget.prototype.addEventListener;
      window.__listeners = [];
      EventTarget.prototype.addEventListener = function(type, fn, opts) {
        if (this.getAttribute && this.getAttribute('data-testid') === 'menu-toggle') {
          window.__listeners.push({ type, fn: fn.toString().substring(0, 100) });
        }
        return orig.call(this, type, fn, opts);
      };
    })();
    """)

    page.set_viewport_size({"width": 375, "height": 812})
    page.goto('https://127.0.0.1:5110/nexifynewweb/', timeout=15000)
    page.wait_for_load_state("load")
    page.wait_for_timeout(500)

    listeners = page.evaluate("() => window.__listeners")
    print(f"Listeners added to toggle: {listeners}")
    browser.close()
