    messages = []
    errors = []
    page.on('console', lambda msg: messages.append(f'[{msg.type}] {msg.text}'))
    page.on('pageerror', lambda err: errors.append(str(err)))

    page.goto('https://127.0.0.1:5110/nexifynewweb/', wait_until='domcontentloaded')
    page.wait_for_timeout(2000)

    # Check scripts loaded
    scripts = page.evaluate('''() => {
        return Array.from(document.querySelectorAll(\"script[src]\")).map(s => s.src);
    }''')
    print('Scripts:', scripts)

    # Check toggle exists
    toggle = page.query_selector('[data-testid=\"menu-toggle\"]')
    print('Toggle exists:', toggle is not None)

    # Check visibility
    if toggle:
        print('Toggle visible:', toggle.is_visible())
        box = toggle.bounding_box()
        print('Toggle bounding box:', box)

    # Check if initNavOverlay ran
    result = page.evaluate('''() => {
        const toggle = document.querySelector(\"[data-testid='menu-toggle']\");
