            navId: nav ? nav.id : null,
            toggleAriaExpanded: toggle ? toggle.getAttribute('aria-expanded') : null
        };
    }''')
    print('State:', result)

    # Check event listeners count
    listener_count = page.evaluate('''() => {
        const toggle = document.querySelector(\".menu-toggle\");
        // Can't directly count listeners, but check if onclick works
        let clicked = false;
        const original = toggle.click.bind(toggle);
        return typeof toggle.onclick;
    }''')
    print('onclick type:', listener_count)

    # Try tapping
    if toggle:
        toggle.tap()
        page.wait_for_timeout(500)

    result2 = page.evaluate('''() => {
        const toggle = document.querySelector(\".menu-toggle\");
        const nav = document.querySelector(\".main-nav\");
        return {
            navClass: nav ? nav.className : null,
            toggleClass: toggle ? toggle.className : null,
            ariaExpanded: toggle ? toggle.getAttribute('aria-expanded') : null,
            bodyOverflow: document.body.style.overflow
        };
    }''')
    print('After TAP:', result2)

    page.screenshot(path='/tmp/mobile_tap_after.png', full_page=False)

    print('Console messages:', messages)
    print('Page errors:', errors)

    browser.close()
