  if (!toggle || !nav) return;

  // Remove any legacy click listeners left by old main.js by replacing node
  // (cloneNode strips all event listeners attached via addEventListener)
  const cleanToggle = toggle.cloneNode(true);
  toggle.parentNode.replaceChild(cleanToggle, toggle);
  // Re-query so all references point to the fresh node
  const btn = document.querySelector('[data-testid="menu-toggle"]');
  if (!btn) return;

  // ── Helpers ──────────────────────────────────────────────
  /**
   * Close the mobile nav and restore state.
   * @param {boolean} [returnFocus=true] — return focus to toggle button
   */
  function closeNav(returnFocus) {
    nav.classList.remove('is-open');
    btn.classList.remove('is-open');
    if (overlay) overlay.classList.remove('is-visible');
    document.body.style.overflow = '';
    btn.setAttribute('aria-expanded', 'false');
    btn.setAttribute('aria-label', 'Άνοιγμα μενού');
    if (returnFocus !== false) btn.focus();
  }

  function openNav() {
    nav.classList.add('is-open');
    btn.classList.add('is-open');
    if (overlay) overlay.classList.add('is-visible');
    document.body.style.overflow = 'hidden';
    btn.setAttribute('aria-expanded', 'true');
    btn.setAttribute('aria-label', 'Κλείσιμο μενού');
    // Move focus to first focusable element inside nav
    const firstFocusable = nav.querySelector('a, button, [tabindex]');
    if (firstFocusable) firstFocusable.focus();
  }

  // ── Toggle click ──────────────────────────────────────────
  btn.addEventListener('click', function () {
    if (nav.classList.contains('is-open')) {
      closeNav(true);
    } else {
      openNav();
    }
  });

  // ── Close on overlay (outside) click ─────────────────────
  if (overlay) {
    overlay.addEventListener('click', function () {
      if (nav.classList.contains('is-open')) closeNav(true);
    });
  }

  // ── Close on Esc key ──────────────────────────────────────
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape' && nav.classList.contains('is-open')) {
      closeNav(true);
    }
  });

  // ── Focus trap while menu is open ─────────────────────────
  nav.addEventListener('keydown', function (e) {
    if (!nav.classList.contains('is-open')) return;
    if (e.key !== 'Tab') return;

    const focusable = Array.from(nav.querySelectorAll(
      'a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])'
    )).filter(function (el) { return el.offsetParent !== null; });

    if (focusable.length === 0) return;

    const first = focusable[0];
    const last  = focusable[focusable.length - 1];

    if (e.shiftKey) {
      // Shift+Tab: if on first → jump to toggle button (exit trap)
      if (document.activeElement === first) {
        e.preventDefault();
        btn.focus();
      }
    } else {
      // Tab: if on last → cycle back to first
      if (document.activeElement === last) {
        e.preventDefault();
        first.focus();
      }
    }
  });

  // ── Close on nav-link click ───────────────────────────────
  nav.querySelectorAll('a').forEach(function (link) {
    link.addEventListener('click', function () {
      if (nav.classList.contains('is-open')) {
        // Don't steal focus — page is navigating
        closeNav(false);
      }
    });
  });

})();

